def hex_to_rgb(colour):
    c = colour.lstrip("#")
    return [int(c[i:i + 2], 16) for i in (0, 2, 4)]

def rgb_to_hex(red, green, blue):
    return f"#{red:02x}{green:02x}{blue:02x}"

def hex_to_rgb(colour):
    n = int(colour[1:], 16)
    return [n // 65536, n // 256 % 256, n % 256]

def rgb_to_hex(red, green, blue):
    return "#" + format(red * 65536 + green * 256 + blue, "06x")
